import { randomUUID } from 'node:crypto';
import { BeforeInsert, PrimaryColumn } from 'typeorm';

// Base class: a UUID primary key generated by the app, so no database extension is needed.
export abstract class IdEntity {
  @PrimaryColumn('uuid')
  id: string;

  @BeforeInsert()
  assignId() {
    this.id ??= randomUUID();
  }
}
